class KeyStore
  def initialize
    @store = {}
  end

  def store(key, value)
    @store[key] = value
  end

  def fetch(key, &block)
    return @store[key] if @store.key?(key)
    block.call if block
  end
end

class TallyingKeyStore < KeyStore
  attr_reader :hits, :misses

  def initialize
    super
    @hits = 0
    @misses = 0
  end

  def fetch(key, &block)
    if @store.key?(key)
      @hits += 1
    else
      @misses += 1
    end
    super(key, &block)
  end
end
